import random, math
random.seed(4)
D, K, L = 8, 6, 4
vecs = [[random.gauss(0, 1) for _ in range(D)] for _ in range(800)]
planes = [[[random.gauss(0, 1) for _ in range(D)] for _ in range(K)] for _ in range(L)]

def sig(v, t):
    return tuple(1 if sum(a*b for a, b in zip(v, p)) > 0 else 0 for p in planes[t])

tables = [{} for _ in range(L)]
for i, v in enumerate(vecs):
    for t in range(L):
        tables[t].setdefault(sig(v, t), []).append(i)

def dist(a, b):
    return math.sqrt(sum((x-y)**2 for x, y in zip(a, b)))

q = vecs[0]
cands = {i for t in range(L) for i in tables[t].get(sig(q, t), [])}
truth = set(sorted(range(len(vecs)), key=lambda i: dist(vecs[i], q))[:10])
got = set(sorted(cands, key=lambda i: dist(vecs[i], q))[:10])
print('candidates: %d, recall@10: %.2f (similar vectors collide)' % (len(cands), len(got & truth)/10))

import math

a = [3.0, 4.0]   # magnitude 5
b = [6.0, 8.0]   # same direction, magnitude 10
c = [-4.0, 3.0]  # different direction

def l2(x, y):
    return math.dist(x, y)

def cos_sim(x, y):
    return sum(a*b for a, b in zip(x, y)) / (math.dist(x, [0]*len(x)) * math.dist(y, [0]*len(y)))

print('a vs b: L2=%.2f (far!) cosine=%.2f (identical direction)' % (l2(a, b), cos_sim(a, b)))
print('a vs c: L2=%.2f cosine=%.2f' % (l2(a, c), cos_sim(a, c)))
print('text embeddings: normalize, then cosine (or L2 on normalized = same ranking)')
